import React from "react";
import Sidebar from "./Sidebar";

export default function CustomerDashboard({ onLogout }) {
  const [active, setActive] = React.useState("dashboard");
  const [searchQuery, setSearchQuery] = React.useState("");
  const [showSearchForm, setShowSearchForm] = React.useState(false);
  const [searchFilters, setSearchFilters] = React.useState({
    name: "",
    location: "",
    city: "",
    pincode: "",
    area: "",
  });

  const popularVehicles = [
    { name: "Honda Activa 6G", type: "Bike", price: "₹249/day", location: "1.2 km away" },
    { name: "Maruti Swift", type: "Car", price: "₹1299/day", location: "2.4 km away" },
    { name: "Tata Nexon", type: "SUV", price: "₹1599/day", location: "3.0 km away" },
  ];

  const recentBookings = [
    { name: "Hyundai i20", type: "Car", price: "₹1499/day", location: "Booked today" },
    { name: "Honda Activa 6G", type: "Bike", price: "₹249/day", location: "Booked yesterday" },
